package app.truemotion.vector;
import java.util.*;
/** Continuous native clips, with baked transform keys instead of a decoder per cel. */
public final class VectorMediaCompile {
 static final class Clip {String id;int from,to;final ArrayList<VectorDocument.Shape> poses=new ArrayList<VectorDocument.Shape>();}
 static List<Clip> clips(VectorDocument d){ArrayList<Clip> out=new ArrayList<Clip>();Map<String,Clip> active=new LinkedHashMap<String,Clip>();for(int f=0;f<=d.frames;f++){Set<String> present=new HashSet<String>();if(f<d.frames)for(VectorDocument.Shape s:d.poseFrame(f))if(s.isMedia()&&d.time(f)>=s.mediaStart&&d.time(f)<s.mediaStart+s.mediaDuration){present.add(s.id);Clip c=active.get(s.id);if(c==null){c=new Clip();c.id=s.id;c.from=f;active.put(s.id,c);out.add(c);}c.to=f+1;c.poses.add(s);}for(Iterator<String> i=active.keySet().iterator();i.hasNext();)if(!present.contains(i.next()))i.remove();}return out;}
 public static int count(VectorDocument d){return clips(d).size();}
 static String property(String name,Clip c,boolean audio){StringBuilder x=new StringBuilder("<"+name+">");String previous=null;for(int i=0;i<c.poses.size();i++){VectorDocument.Shape s=c.poses.get(i);String value=name.equals("location")?VectorDocument.n(s.x)+","+VectorDocument.n(s.y)+",0":name.equals("scale")?VectorDocument.n(s.sx)+","+VectorDocument.n(s.sy):name.equals("rotation")?VectorDocument.n(s.angle):VectorDocument.n(s.opacity);if(value.equals(previous)&&i!=c.poses.size()-1)continue;previous=value;double t=c.poses.size()==1?0:i/(double)c.poses.size();x.append("<kf t=\"").append(VectorDocument.n(t)).append("\" v=\"").append(value).append("\" e=\"linear\"/>");}return x.append("</"+name+">").toString();}
 public static String xml(VectorDocument d,long[] id){StringBuilder x=new StringBuilder();for(Clip c:clips(d)){VectorDocument.Shape s=c.poses.get(0);int start=d.time(c.from),end=d.time(c.to),offset=Math.max(0,start-s.mediaStart)+s.mediaOffset;String attrs=" id=\""+(++id[0])+"\" label=\""+VectorDocument.escape(s.name)+"\" startTime=\""+start+"\" endTime=\""+end+"\" inTime=\""+offset+"\" outTime=\""+(offset+end-start)+"\"";if(s.isAudio()){x.append("<audio"+attrs+" src=\""+VectorDocument.escape(s.mediaUri)+"\"><volume value=\""+VectorDocument.n(s.opacity)+"\"/></audio>");continue;}int w=s.imageFrame[0],h=s.imageFrame[1];x.append("<shape"+attrs+" fillType=\"media\" fillVideo=\""+VectorDocument.escape(s.mediaUri)+"\" mediaFillMode=\"stretch\"><transform>");for(String p:new String[]{"location","scale","rotation","opacity"})x.append(property(p,c,false));x.append("</transform><path d=\"M "+(-w/2d)+" "+(-h/2d)+" L "+w/2d+" "+(-h/2d)+" L "+w/2d+" "+h/2d+" L "+(-w/2d)+" "+h/2d+" Z\"/></shape>");}return x.toString();}
}
